use super::*;
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation};
fn stock()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1<<24,maximum_copy_bytes:1<<28,maximum_capacity_bytes:1<<28,maximum_release_bytes:1<<28,maximum_depth:4096}}
fn advance_original(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,owner:&mut SnapshotReadRegistryBirth,g:RetainedCloneGrant)->RetainedCloneStep{caller.turn_with_decoder(g,decoder,|cx|{if g.maximum_items==0||g.maximum_depth==0{return Ok(RetainedCloneStep::Progress(Default::default()))}let result=cx.with_native_receiving(|control|owner.advance(g,control));cx.consume_fuel(owner.last_turn_work());let p=result.as_ref().map(|step|step.progress()).unwrap_or_else(|error:&ValueError|error.retained_progress());let issued=cx.receiving_issued_grant().unwrap();cx.consume_receiving_retained(issued,p)?;Ok(result?)}).unwrap()}
fn close_original(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,owner:&mut SnapshotReadRegistryBirth,g:RetainedCloneGrant)->RetainedCloneStep{caller.turn_with_decoder(g,decoder,|cx|cx.with_original_retirement(|cx|{let result=cx.with_native_retirement(|control|owner.close_step(g,control));let p=result.as_ref().map(|step|step.progress()).unwrap_or_else(|error|error.retained_progress());cx.consume_fuel(owner.last_turn_work());cx.consume_retained(p)?;Ok(result?)})).unwrap()}

fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
#[test]
fn registry_birth_requires_original_work_before_any_physical_effect(){
 let law:serde_json::Value=serde_json::from_str(include_str!("./🧫️fixtures/🔣️.json")).unwrap();let mut caller=OriginalJobFixtureCaller::admit(OperationId(582),Generation(28),stock(),||Some(1),u64::MAX,1<<24);let mut decoder=OriginalJobDecodeOwner::empty();let mut owner=SnapshotReadRegistryBirth::new();let g=grant(owner.demands().unwrap());
 let(result,heap)=observe(||caller.turn_with_decoder(g,&mut decoder,|cx|cx.with_original_work_loan(0,u64::MAX,|cx|{let step=cx.with_native_receiving(|control|owner.advance(g,control))?;let issued=cx.receiving_issued_grant().unwrap();cx.consume_receiving_retained(issued,step.progress())?;Ok(step)})));assert_eq!(result.unwrap().progress(),Default::default());assert_eq!(owner.last_turn_work(),0);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(owner.registry.is_none());
 advance_original(&mut caller,&mut decoder,&mut owner,g);assert_eq!(owner.last_turn_work(),law["maximumBirthWork"].as_u64().unwrap());caller.cancel().cancel_now();owner.begin_close();for _ in 0..100{if owner.terminal_is_empty(){break}let g=grant(owner.close_demands().unwrap());close_original(&mut caller,&mut decoder,&mut owner,g);}assert!(owner.terminal_is_empty());while !decoder.terminal_is_empty(){caller.turn(stock(),|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;decoder.close_on_source(cx)?;Ok(())})).unwrap();}caller.retire(stock());
}
#[test]
fn original_registry_birth_keeps_four_kib_quantum_fifo_and_exact_cumulative_custody(){
 let law:serde_json::Value=serde_json::from_str(include_str!("./🧫️fixtures/🔣️.json")).unwrap();
 let mut full_case=0;for cut in law["cancelAt"].as_array().unwrap().iter().map(|x|x.as_u64().unwrap()as usize).chain(std::iter::repeat_n(usize::MAX,law["queue"].as_array().unwrap().len())){
  let mut caller=OriginalJobFixtureCaller::admit(OperationId(581),Generation(27),stock(),||Some(1),u64::MAX,1<<24);let mut decoder=OriginalJobDecodeOwner::empty();let capacity_baseline=caller.cumulative_receipt().retained_capacity_bytes;let mut owner=SnapshotReadRegistryBirth::new();let(mut born,mut released)=(0,0);
  for turn in 0..50{if turn==cut||owner.ready().unwrap(){break;}let d=owner.demands().unwrap();assert!(d.copy_bytes<=4096);let g=grant(d);
   for axis in 0..4{let mut short=g;match axis{0=>short.maximum_items=0,1 if d.copy_bytes!=0=>short.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes!=0=>short.maximum_capacity_bytes=d.capacity_bytes-1,3=>short.maximum_depth=0,_=>continue}let admitted=caller.cumulative_receipt().retained_capacity_bytes;let(step,heap)=observe(||advance_original(&mut caller,&mut decoder,&mut owner,short));assert_eq!(step.progress(),Default::default());assert_eq!(caller.cumulative_receipt().retained_capacity_bytes,admitted);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
   let admitted=caller.cumulative_receipt().retained_capacity_bytes;let(step,heap)=observe(||advance_original(&mut caller,&mut decoder,&mut owner,g));assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert_eq!(caller.cumulative_receipt().retained_capacity_bytes-admitted,heap.requested_bytes);born+=heap.requested_bytes;released+=heap.released_bytes;
  }
  if cut==usize::MAX{assert!(owner.ready().unwrap());let identity=owner.registry.as_ref().unwrap().identity();let(registry,p)=owner.take(grant(Default::default())).unwrap().unwrap();assert!(p.fits(grant(Default::default())));assert_eq!(registry.identity(),identity);
   for row in std::iter::once(&law["queue"][full_case]){let source=Arc::new(37u64);let mut oracle:std::collections::VecDeque<usize>=(0..law["capacity"].as_u64().unwrap()as usize).collect();let mut leases=Vec::new();for index in 0..row["issue"].as_u64().unwrap()as usize{let lease=registry.try_issue(source.clone()).unwrap_or_else(|_|panic!("original funded registry issue"));assert_eq!(lease.index as usize,index);assert_eq!(Some(lease.index as usize),oracle.pop_front());leases.push((lease.index,lease.generation,Some(lease)));}
    for index in row["return"].as_array().unwrap().iter().map(|x|x.as_u64().unwrap()as usize){let(slot,generation,lease)=&mut leases[index];drop(lease.take());drop(registry.try_take(*slot,*generation).unwrap());oracle.push_back(*slot as usize);}
    for expected in row["next"].as_array().unwrap().iter().map(|x|x.as_u64().unwrap()as usize){let lease=registry.try_issue(source.clone()).unwrap_or_else(|_|panic!("original queue return issue"));assert_eq!(lease.index as usize,expected);assert_eq!(Some(expected),oracle.pop_front());leases.push((lease.index,lease.generation,Some(lease)));}
    for(index,generation,lease)in leases{if let Some(lease)=lease{drop(lease);drop(registry.try_take(index,generation).unwrap());}}
   }
   full_case+=1;*owner.retirement=Some(SnapshotReadRegistryAliasRetirement::new(registry));owner.taken=false;
  }
  caller.cancel().cancel_now();owner.begin_close();for _ in 0..100{if owner.terminal_is_empty(){break;}let g=grant(owner.close_demands().unwrap());let admitted=caller.cumulative_receipt().retained_capacity_bytes;let(step,heap)=observe(||close_original(&mut caller,&mut decoder,&mut owner,g));assert_eq!(caller.cumulative_receipt().retained_capacity_bytes-admitted,heap.requested_bytes);assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(step.progress().fits(g));born+=heap.requested_bytes;released+=heap.released_bytes;}assert!(owner.terminal_is_empty());assert_eq!(born,released);assert_eq!(caller.cumulative_receipt().retained_capacity_bytes-capacity_baseline,born);while !decoder.terminal_is_empty(){caller.turn(stock(),|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;decoder.close_on_source(cx)?;Ok(())})).unwrap();}caller.retire(stock());
 }
}
